t.script:

document.addEventListener('DOMContentLoaded', function() {
    let currentFilter = 'all';
    let currentPage = 1;
    const pageSize = 20;
    let searchValue = '';
    let dateFrom = '';
    let dateTo = '';

    function getFilteredRows() {
        const rows = Array.from(document.querySelectorAll('#orders-tbody tr'));
        return rows.filter(row => {
            // Filter theo trạng thái
            let statusOk = true;
            if (currentFilter === 'new') statusOk = row.dataset.status === 'new';
            else if (currentFilter === 'delivered') statusOk = row.dataset.status === 'delivered';
            else if (currentFilter === 'in_transit') statusOk = ['waiting_pickup', 'picked_up', 'in_transit', 'waiting_delivery'].includes(row.dataset.status);
            else if (currentFilter === 'canceled') statusOk = row.dataset.status === 'canceled';
            // Filter theo search
            let searchOk = true;
            if (searchValue) {
                const orderId = row.children[0].innerText.trim().toLowerCase();
                const receiverName = row.children[1].innerText.trim().toLowerCase();
                const toAddress = row.children[2].innerText.trim().toLowerCase();
                searchOk = orderId.includes(searchValue) || receiverName.includes(searchValue) || toAddress.includes(searchValue);
            }
            // Filter theo ngày
            let dateOk = true;
            if (dateFrom || dateTo) {
                const dateText = row.children[4].innerText.trim();
                const rowDate = new Date(dateText.split(' ')[0].split('/').reverse().join('-'));
                if (dateFrom) {
                    const fromDate = new Date(dateFrom);
                    if (rowDate < fromDate) dateOk = false;
                }
                if (dateTo) {
                    const toDate = new Date(dateTo);
                    if (rowDate > toDate) dateOk = false;
                }
            }
            return statusOk && searchOk && dateOk;
        });
    }

    function renderTable() {
        const rows = Array.from(document.querySelectorAll('#orders-tbody tr'));
        rows.forEach(row => row.style.display = 'none');
        const filteredRows = getFilteredRows();
        const totalPage = Math.max(1, Math.ceil(filteredRows.length / pageSize));
        if (currentPage > totalPage) currentPage = 1;
        filteredRows.slice((currentPage-1)*pageSize, currentPage*pageSize).forEach(row => row.style.display = '');
        const pagin = document.getElementById('orders-pagination');
        pagin.innerHTML = '';

        const prevLi = document.createElement('li');
        prevLi.className = 'page-item' + (currentPage === 1 ? ' disabled' : '');
        const prevLink = document.createElement('a');
        prevLink.className = 'page-link';
        prevLink.href = '#';
        prevLink.innerHTML = '&laquo;';
        prevLink.onclick = function(e) {
            e.preventDefault();
            if (currentPage > 1) {
                currentPage--;
                renderTable();
            }
        };
        prevLi.appendChild(prevLink);
        pagin.appendChild(prevLi);

        for (let i = 1; i <= totalPage; i++) {
            const li = document.createElement('li');
            li.className = 'page-item' + (i === currentPage ? ' active' : '');
            const a = document.createElement('a');
            a.className = 'page-link';
            a.href = '#';
            a.textContent = i;
            a.onclick = function(e) {
                e.preventDefault();
                currentPage = i;
                renderTable();
            };
            li.appendChild(a);
            pagin.appendChild(li);
        }

        const nextLi = document.createElement('li');
        nextLi.className = 'page-item' + (currentPage === totalPage ? ' disabled' : '');
        const nextLink = document.createElement('a');
        nextLink.className = 'page-link';
        nextLink.href = '#';
        nextLink.innerHTML = '&raquo;';
        nextLink.onclick = function(e) {
            e.preventDefault();
            if (currentPage < totalPage) {
                currentPage++;
                renderTable();
            }
        };
        nextLi.appendChild(nextLink);
        pagin.appendChild(nextLi);
    }
    document.querySelectorAll('.btn-filter').forEach(btn => {
        btn.addEventListener('click', function() {
            document.querySelectorAll('.btn-filter').forEach(b => b.classList.remove('active'));
            this.classList.add('active');
            currentFilter = this.dataset.filter;
            currentPage = 1;
            renderTable();
        });
    });

    document.getElementById('btn-search').onclick = function() {
        searchValue = document.getElementById('order-search-input').value.trim().toLowerCase();
        currentPage = 1;
        renderTable();
        renderSearchTag();
        document.getElementById('order-search-input').value = '';
    };

    function renderSearchTag() {
        const tagContainer = document.getElementById('search-tags');
        tagContainer.innerHTML = '';
        if (searchValue) {
            const tag = document.createElement('span');
            tag.className = 'search-tag';
            tag.textContent = searchValue;
            const closeBtn = document.createElement('span');
            closeBtn.className = 'search-tag-close';
            closeBtn.innerHTML = '&times;';
            closeBtn.onclick = function() {
                searchValue = '';
                currentPage = 1;
                renderTable();
                renderSearchTag();
            };
            tag.appendChild(closeBtn);
            tagContainer.appendChild(tag);
        }
    }

    document.getElementById('btn-apply-date').onclick = function() {
        dateFrom = document.getElementById('from-date').value;
        dateTo = document.getElementById('to-date').value;
        currentPage = 1;
        renderTable();
        document.getElementById('date-filter-menu').classList.remove('show');
    };

    document.getElementById('btn-cancel-date').onclick = function() {
        document.getElementById('date-filter-menu').classList.remove('show');
    };

    document.getElementById('btn-all').classList.add('active');
    renderTable();
    renderSearchTag();

    // Date filter menu toggle
    const btnDateFilter = document.getElementById('btn-date-filter');
    const dateMenu = document.getElementById('date-filter-menu');
    btnDateFilter.addEventListener('click', function(e) {
        e.stopPropagation();
        dateMenu.classList.toggle('show');
    });
    document.addEventListener('click', function(e) {
        if (!dateMenu.contains(e.target) && e.target !== btnDateFilter) {
            dateMenu.classList.remove('show');
        }
    });
});
